-- Patch for already-seeded environments only.
--
-- Syncs the Breeding Details section's section_ui_schema to the canonical
-- definition in g2p_register_sections.sql (line
-- 'livestock_breeding_details_section_01'). The seed only INSERTs and never
-- touches an existing row, so environments seeded before that line changed
-- keep the old dialog forever; this re-applies the whole schema by section_id.
--
-- Why: the official staff-ui cannot fill a dialog column from another
-- section's rows ("sibling-table" source) nor cascade one dialog column from
-- another, so the Ear Tag picker rendered EMPTY (and, on Vaccination, the
-- Vaccine list too). Ear Tag is now a text input (server-checked against this
-- submission's animals), Vaccine the plain VACCINE_TYPE list (server-checked
-- against the animal's species), Species is filled by the server from the
-- animal, and dialog conditions use operators the official UI supports.
-- Also: Notifiable Disease / Pregnancy Confirmed are required only while
-- their show-condition holds (conditional "require" action, like
-- disease_type) — a hidden-but-required radio blocked every non-DISEASE
-- event on Next ("Row 1, Notifiable Disease: This field is required").
--
-- 2026-09-22: Pregnancy Confirmation Date now shows only once Pregnancy
-- Confirmed = Yes (single condition on the boolean field itself, not on
-- event_type -- the dialog-table condition engine takes only the LAST
-- show/hide action, not an AND of several; see the note on bt()/br() in
-- patch_ls_health_event_details_sync_ui_schema.sql). Outcome and the
-- Female-only Ear Tag dropdown are NOT in this JSON: Outcome only shows
-- once Expected Calving Date has passed, which needs "today" -- not
-- expressible by this condition engine (fields/fixed values only, never
-- the current date) -- so both live in livestock-dialog-overlay.js
-- (wireBreedingOutcome, and the femaleOnly filter in wireEvent), backed by
-- G2PRegisterDomainServiceBreeding._validate_female_only server-side.
-- Generated from the seed line; keep the two in sync.
UPDATE "public"."g2p_register_sections"
SET section_ui_schema = '{"panels": [{"panels": [{"widgets": [{"widget": "dialog-table", "widget-id": "ls_breeding_details_table", "widget-type": "dialog-table", "widget-label": "Breeding Details", "widget-readonly": false, "widget-data-path": "192c08b0-5403-5167-968a-2676d4af2879.records", "widget-data-columns": [{"widget": "text", "column-key": "ear_tag_id", "widget-type": "input", "widget-label": "Ear Tag / Secondary Identifier", "widget-autofill": {"fields": {"age": "age", "species": "species"}, "matchField": "ear_tag_id", "sourceWidgetId": "ls_animal_details_table"}, "widget-readonly": false, "widget-required": false, "widget-data-path": "ear_tag_id", "widget-placeholder": "ET + 10 digits, e.g. ET0000000123", "widget-data-options": {"actions": [{"action": "require", "condition": {"field": "ear_tag_id", "operator": "empty"}}]}}, {"widget": "select", "column-key": "species", "widget-type": "input", "widget-label": "Species", "widget-readonly": true, "widget-data-path": "species", "widget-data-source": {"type": "api", "method": "POST", "params": {"page_size": 500, "attribute_id": "LIVESTOCK_TYPE"}, "service": "attributes", "endpoint": "values", "labelKey": "value_display", "valueKey": "value_id"}}, {"widget": "text", "column-key": "age", "widget-type": "input", "widget-label": "Age", "widget-readonly": true, "widget-data-path": "age"}, {"widget": "select", "column-key": "event_type", "widget-type": "input", "widget-label": "Breeding Type", "widget-readonly": false, "widget-required": false, "widget-data-path": "event_type", "widget-data-source": {"type": "static", "options": [{"label": "NATURAL", "value": "NATURAL"}, {"label": "Artificial Insemination", "value": "AI"}]}, "widget-data-options": {"actions": [{"action": "require", "condition": {"field": "event_type", "operator": "empty"}}]}}, {"widget": "date", "column-key": "breeding_date", "widget-type": "input", "widget-label": "Breeding Date", "widget-readonly": false, "widget-data-path": "breeding_date", "widget-data-format": {"dateFormat": "DD/MM/YYYY", "inputMethod": "picker", "dateConstraint": "any"}, "widget-data-placeholder": "dd_mm_yyyy", "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "operator": "notEmpty"}}]}}, {"widget": "text", "column-key": "sire_or_semen_id", "widget-type": "input", "widget-label": "Sire / Semen Source", "widget-readonly": false, "widget-data-path": "sire_or_semen_id", "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "operator": "notEmpty"}}]}}, {"widget": "select", "column-key": "location", "widget-type": "input", "widget-label": "Location", "widget-readonly": false, "widget-data-path": "location", "widget-data-source": {"type": "static", "options": [{"label": "HOME", "value": "HOME"}, {"label": "VETERINARY", "value": "VETERINARY"}, {"label": "MARKET", "value": "MARKET"}, {"label": "FIELD", "value": "FIELD"}, {"label": "QUARANTINE_CENTER", "value": "QUARANTINE_CENTER"}, {"label": "OTHER", "value": "OTHER"}]}, "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "operator": "notEmpty"}}]}}, {"widget": "text", "column-key": "location_details", "widget-type": "input", "widget-label": "Location Details", "widget-readonly": false, "widget-data-path": "location_details", "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "operator": "notEmpty"}}]}}, {"widget": "text", "column-key": "ai_technician_name", "widget-type": "input", "widget-label": "AI Technician", "widget-readonly": false, "widget-data-path": "ai_technician_name", "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "value": "AI", "operator": "equals"}}, {"action": "require", "condition": {"field": "event_type", "value": "AI", "operator": "equals"}}]}}, {"widget": "text", "column-key": "ai_technique", "widget-type": "input", "widget-label": "Technique Used", "widget-readonly": false, "widget-data-path": "ai_technique", "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "value": "AI", "operator": "equals"}}]}}, {"widget": "text", "column-key": "semen_batch_number", "widget-type": "input", "widget-label": "Semen Batch Number", "widget-readonly": false, "widget-data-path": "semen_batch_number", "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "value": "AI", "operator": "equals"}}]}}, {"widget": "date", "column-key": "expected_calving_date", "widget-type": "input", "widget-label": "Expected Calving Date", "widget-readonly": false, "widget-data-path": "expected_calving_date", "widget-data-format": {"dateFormat": "DD/MM/YYYY", "inputMethod": "picker"}, "widget-data-placeholder": "dd_mm_yyyy", "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "operator": "notEmpty"}}]}}, {"widget": "radio", "column-key": "pregnancy_confirmed", "widget-type": "input", "widget-label": "Pregnancy Confirmed", "widget-readonly": false, "widget-data-path": "pregnancy_confirmed", "widget-data-source": {"type": "static", "options": [{"label": "YES", "value": true}, {"label": "NO", "value": false}]}, "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "operator": "notEmpty"}}, {"action": "require", "condition": {"field": "event_type", "operator": "notEmpty"}}]}}, {"widget": "date", "column-key": "pregnancy_confirmation_date", "widget-type": "input", "widget-label": "Pregnancy Confirmation Date", "widget-readonly": false, "widget-data-path": "pregnancy_confirmation_date", "widget-data-format": {"dateFormat": "DD/MM/YYYY", "inputMethod": "picker"}, "widget-data-placeholder": "dd_mm_yyyy", "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "pregnancy_confirmed", "value": true, "operator": "equals"}}]}}, {"widget": "select", "column-key": "outcome", "widget-type": "input", "widget-label": "Outcome", "widget-readonly": false, "widget-data-path": "outcome", "widget-data-source": {"type": "static", "options": [{"label": "PENDING", "value": "PENDING"}, {"label": "SUCCESSFUL", "value": "SUCCESSFUL"}, {"label": "FAILED", "value": "FAILED"}]}, "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "operator": "notEmpty"}}]}}, {"widget": "text", "column-key": "notes", "widget-type": "input", "widget-label": "Notes", "widget-readonly": false, "widget-data-path": "notes", "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "operator": "notEmpty"}}]}}], "widget-data-operations": {"add": true, "edit": true, "remove": true}, "widget-data-dialog-title-add": "Add Breeding Details", "widget-data-dialog-title-edit": "Edit Breeding Details"}], "panel-id": "vertical_panel_ls_breeding_details_1", "panel-orientation": "vertical"}], "panel-id": "horizontal_panel_ls_breeding_details", "panel-orientation": "horizontal"}], "section-id": "livestock_breeding_details_section_01", "section-title": "Breeding Details", "section-editable": true, "section-required-for-submit": false}'::jsonb
WHERE section_id = 'livestock_breeding_details_section_01';
